text:
#stage {
  --ground: #FAF8F5;
  --main: #9C7156;
  --second: #2B2928;
  --accent: #C8962E;
  color: var(--second);
  font-family: var(--sans, "Plus Jakarta Sans", system-ui, sans-serif);
  background: var(--ground);
}
.ground {
  position: absolute;
  inset: 0;
  background: radial-gradient(120% 90% at 50% 20%, color-mix(in srgb, var(--accent) 14%, var(--ground)), var(--ground));
}
.words {
  position: absolute;
  margin: 0;
  display: flex;
  flex-direction: column;
  gap: 16px;
  z-index: 10;
}
.words > * { margin: 0; }
.line {
  font-family: var(--display, "Fraunces", serif);
  font-size: 68px;
  line-height: 1.15;
  font-weight: 700;
  color: var(--second);
  letter-spacing: -0.01em;
}
.sub {
  font-family: var(--sans, system-ui, sans-serif);
  font-size: 30px;
  line-height: 1.35;
  font-weight: 500;
  color: color-mix(in srgb, var(--second) 75%, var(--ground));
}
.pill-badge {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  background: color-mix(in srgb, var(--main) 12%, transparent);
  border: 1px solid color-mix(in srgb, var(--main) 28%, transparent);
  padding: 8px 22px;
  border-radius: 999px;
  color: var(--main);
  font-size: 22px;
  font-weight: 700;
  letter-spacing: 0.05em;
  text-transform: uppercase;
  width: fit-content;
}
.art-center {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  overflow: visible;
}
.ceramic-card {
  position: absolute;
  background: #FFFFFF;
  border-radius: 28px;
  box-shadow: 0 16px 40px rgba(43, 41, 40, 0.08);
  border: 1px solid color-mix(in srgb, var(--second) 8%, transparent);
  overflow: hidden;
}
